import builtins
import contextlib
import io
import re

CODE_RE = re.compile(r"<code>(.*?)</code>", re.DOTALL)

SAFE_BUILTIN_NAMES = (
    "print len sum range round sorted min max abs any all enumerate zip "
    "list dict set tuple str int float bool ValueError TypeError Exception"
).split()


class FinalAnswer(Exception):
    def __init__(self, value):
        super().__init__("final answer")
        self.value = value


class MaxStepsError(Exception):
    pass


def make_namespace(tools, authorized_imports):
    allowed = set(authorized_imports)

    def guarded_import(name, *args, **kwargs):
        root = name.split(".")[0]
        if root not in allowed:
            raise ImportError(f"import of {root!r} is not allowed")
        return builtins.__import__(name, *args, **kwargs)

    safe = {name: getattr(builtins, name) for name in SAFE_BUILTIN_NAMES}
    safe["__import__"] = guarded_import

    def final_answer(value):
        raise FinalAnswer(value)

    namespace = {"__builtins__": safe, "final_answer": final_answer}
    namespace.update(tools)
    return namespace


def run_code_agent(task, model, tools, authorized_imports=(), max_steps=6):
    namespace = make_namespace(tools, authorized_imports)
    history = []
    for _ in range(max_steps):
        text = model(task, list(history))
        found = CODE_RE.search(text)
        if found is None:
            history.append({"code": None,
                            "observation": "No <code> block found in your reply"})
            continue
        code = found.group(1)
        buffer = io.StringIO()
        try:
            with contextlib.redirect_stdout(buffer):
                exec(code, namespace)
        except FinalAnswer as final:
            return {"answer": final.value, "steps": len(history) + 1,
                    "history": history}
        except Exception as exc:
            observation = f"{type(exc).__name__}: {exc}"
        else:
            observation = buffer.getvalue().strip()
        history.append({"code": code, "observation": observation})
    raise MaxStepsError(f"no final answer within {max_steps} steps")
